      visual_intent: visualIntent,
      must_show: mustShow,
      must_not_show: mustNotShow,
      queries_en: queries,
      preferred_media_type: preferredMediaType,
    });
  }

  totalShots += sanitizedShots.length;

  sanitizedScenes.push({
    scene_id: sceneId,
    narration: sceneNarration,
    evidence_ids: uniqueEvidence,
    evidence_uuids: uniqueEvidence.map((id) => evidenceMap[id]),
    shots: sanitizedShots,
  });
}

if (totalShots !== Number(ctx.target_shots)) {
  throw new Error(
    'total shot count mismatch: ' + totalShots +
    ', required exactly ' + ctx.target_shots
  );
}

const joinedNarration = clean(
  sanitizedScenes.map((scene) => scene.narration).join(' ')
);
if (!joinedNarration) {
  throw new Error('canonical narration is empty');
}

const words = joinedNarration.split(/\s+/u).filter(Boolean);
if (
  words.length < Number(ctx.word_min) ||
