    ', required ' + ctx.word_min + '-' + ctx.word_max
  );
}

const repairUsage = body.usageMetadata && typeof body.usageMetadata === 'object'
  ? body.usageMetadata
  : {};
const firstResponse = $('Generate Storyboard').first().json;
const firstBody = firstResponse.body && typeof firstResponse.body === 'object'
  ? firstResponse.body
  : firstResponse;
const firstUsage = firstBody.usageMetadata && typeof firstBody.usageMetadata === 'object'
  ? firstBody.usageMetadata
  : {};
const toCount = (value) => Number.isFinite(Number(value)) ? Number(value) : 0;
const usage = {
  promptTokenCount:
    toCount(firstUsage.promptTokenCount) + toCount(repairUsage.promptTokenCount),
  candidatesTokenCount:
    toCount(firstUsage.candidatesTokenCount) + toCount(repairUsage.candidatesTokenCount),
  totalTokenCount:
    toCount(firstUsage.totalTokenCount) + toCount(repairUsage.totalTokenCount),
};

return {
  json: {
    script_run_id: ctx.script_run_id,
    model: ctx.model,
    storyboard: {
      narration: joinedNarration,
      scenes: sanitizedScenes,
